import {
  rankTimelessSeeds,
  timelessJewelQuerySchema,
  type TimelessJewelQuery,
  type TimelessJewelResult
} from "@poe-odyssey/core";
import {
  AlertTriangle,
  Clipboard,
  ExternalLink,
  Heart,
  Search,
  Share2,
  Sparkles,
  Trash2
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { PageTitle } from "../App";
import {
  timelessDatasetNotice,
  timelessSeedRecords,
  timelessStatOptions
} from "../content/toolboxData";
import {
  removeTimelessFavorite,
  saveTimelessFavorite,
  timelessFavorites
} from "../storage";

const conquerors: Record<TimelessJewelQuery["jewelType"], string[]> = {
  "Lethal Pride": ["Kaom", "Rakiata", "Kiloava", "Akoya"],
  "Brutal Restraint": ["Deshret", "Balbala", "Asenath", "Nasima"],
  "Elegant Hubris": ["Cadiro", "Victario", "Chitus", "Caspiro"],
  "Glorious Vanity": ["Xibaqua", "Zerphi", "Ahuana", "Doryani"],
  "Militant Faith": ["Venarius", "Maxarius", "Dominus", "Avarius"]
};

const seedRanges: Record<TimelessJewelQuery["jewelType"], [number, number]> = {
  "Lethal Pride": [10000, 18000],
  "Brutal Restraint": [500, 8000],
  "Elegant Hubris": [2000, 160000],
  "Glorious Vanity": [100, 8000],
  "Militant Faith": [2000, 10000]
};

const defaultQuery: TimelessJewelQuery = {
  jewelType: "Lethal Pride",
  conqueror: "Kaom",
  socketId: "socket-1",
  seedStart: 10000,
  seedEnd: 18000,
  minimumScore: 1,
  stats: timelessStatOptions.slice(0, 4).map((stat, index) => ({
    ...stat,
    weight: index === 0 ? 5 : 2,
    minimumOccurrences: index === 0 ? 1 : 0,
    excluded: false
  }))
};

function favoriteKey(result: TimelessJewelResult) {
  return `${result.conqueror}:${result.socketId}:${result.seed}`;
}

export function TimelessPage() {
  const [query, setQuery] = useState<TimelessJewelQuery>(() => {
    const encoded = new URLSearchParams(window.location.hash.split("?")[1] ?? "").get("query");
    if (!encoded) return defaultQuery;
    try {
      return timelessJewelQuerySchema.parse(JSON.parse(decodeURIComponent(encoded)));
    } catch {
      return defaultQuery;
    }
  });
  const [searched, setSearched] = useState(false);
  const [favorites, setFavorites] = useState<Array<TimelessJewelResult & { key: string }>>([]);
  const [message, setMessage] = useState("");

  useEffect(() => {
    void timelessFavorites().then(setFavorites);
  }, []);

  const results = useMemo(() => searched ? rankTimelessSeeds(
    query,
    timelessSeedRecords,
    {
      verified: timelessDatasetNotice.verified,
      tradeBaseUrl: "https://pathofexile.tw/trade/search/亡焰咒海"
    }
  ).slice(0, 50) : [], [query, searched]);

  function patch(next: Partial<TimelessJewelQuery>) {
    setQuery({ ...query, ...next });
    setSearched(false);
  }

  function patchStat(id: string, next: Partial<TimelessJewelQuery["stats"][number]>) {
    patch({ stats: query.stats.map((stat) => stat.id === id ? { ...stat, ...next } : stat) });
  }

  function runSearch() {
    setSearched(true);
    localStorage.setItem("poe-odyssey-timeless-last-query", JSON.stringify(query));
    setMessage("搜尋完成；交易前請依警告在 PoB 驗證。");
  }

  async function share() {
    const encoded = encodeURIComponent(JSON.stringify(query));
    const url = new URL(window.location.href);
    url.hash = `#/timeless?query=${encoded}`;
    await navigator.clipboard.writeText(url.toString());
    setMessage("搜尋設定分享連結已複製。");
  }

  async function toggleFavorite(result: TimelessJewelResult) {
    const key = favoriteKey(result);
    if (favorites.some((entry) => entry.key === key)) {
      await removeTimelessFavorite(key);
      setFavorites(favorites.filter((entry) => entry.key !== key));
    } else {
      await saveTimelessFavorite(result);
      setFavorites([...favorites, { ...result, key }]);
    }
  }

  return (
    <div className="page timeless-page">
      <PageTitle
        eyebrow="TIMELESS JEWEL LAB · POB-FIRST"
        title="永恆珠寶搜尋"
        description="用權重、最低次數與排除條件排名 Seed，保存候選並複製成 PoB 物品文字。"
      >
        <button className="button secondary" onClick={() => void share()}><Share2 size={15} /> 分享設定</button>
      </PageTitle>

      <div className="policy-banner timeless-warning">
        <AlertTriangle size={20} />
        <div>
          <strong>{timelessDatasetNotice.title}</strong>
          <p>{timelessDatasetNotice.detail}</p>
        </div>
      </div>

      {message && <div className="inline-message">{message}</div>}

      <section className="timeless-layout">
        <div className="panel timeless-query">
          <div className="query-grid">
            <label>
              <span>珠寶 / Jewel</span>
              <select value={query.jewelType} onChange={(event) => {
                const jewelType = event.target.value as TimelessJewelQuery["jewelType"];
                patch({
                  jewelType,
                  conqueror: conquerors[jewelType][0]!,
                  seedStart: seedRanges[jewelType][0],
                  seedEnd: seedRanges[jewelType][1]
                });
              }}>
                {Object.keys(conquerors).map((value) => <option key={value}>{value}</option>)}
              </select>
            </label>
            <label>
              <span>征服者 / Conqueror</span>
              <select value={query.conqueror} onChange={(event) => patch({ conqueror: event.target.value })}>
                {conquerors[query.jewelType].map((value) => <option key={value}>{value}</option>)}
              </select>
            </label>
            <label>
              <span>插槽 / Socket</span>
              <select value={query.socketId} onChange={(event) => patch({ socketId: event.target.value })}>
                <option value="socket-1">插槽 1 · 西北</option>
                <option value="socket-2">插槽 2 · 東側</option>
                <option value="socket-3">插槽 3 · 南側</option>
              </select>
            </label>
            <label>
              <span>最低分數</span>
              <input type="number" value={query.minimumScore} onChange={(event) => patch({ minimumScore: Number(event.target.value) })} />
            </label>
            <label>
              <span>Seed 起點</span>
              <input type="number" value={query.seedStart} onChange={(event) => patch({ seedStart: Number(event.target.value) })} />
            </label>
            <label>
              <span>Seed 終點</span>
              <input type="number" value={query.seedEnd} onChange={(event) => patch({ seedEnd: Number(event.target.value) })} />
            </label>
          </div>

          <div className="timeless-stat-editor">
            <div className="stat-editor-heading"><span>詞綴</span><span>權重</span><span>最低次數</span><span>排除</span></div>
            {query.stats.map((stat) => (
              <div key={stat.id}>
                <span>{stat.label.zhTW}<small>{stat.label.en}</small></span>
                <input type="number" value={stat.weight} onChange={(event) => patchStat(stat.id, { weight: Number(event.target.value) })} />
                <input type="number" min={0} max={10} value={stat.minimumOccurrences} onChange={(event) => patchStat(stat.id, { minimumOccurrences: Number(event.target.value) })} />
                <input type="checkbox" checked={stat.excluded} onChange={(event) => patchStat(stat.id, { excluded: event.target.checked })} />
              </div>
            ))}
          </div>
          <button className="button primary timeless-search-button" onClick={runSearch}><Search size={16} /> 搜尋 {query.seedStart.toLocaleString()}–{query.seedEnd.toLocaleString()}</button>
        </div>

        <aside className="panel timeless-favorites">
          <h3><Heart size={17} /> 收藏候選</h3>
          {favorites.length === 0 ? <p>尚未收藏 Seed。</p> : favorites.map((entry) => (
            <div key={entry.key}>
              <span><strong>{entry.seed}</strong><small>{entry.conqueror} · {entry.socketId}</small></span>
              <button onClick={() => void toggleFavorite(entry)} aria-label={`移除 ${entry.seed}`}><Trash2 size={14} /></button>
            </div>
          ))}
        </aside>
      </section>

      {searched && (
        <section className="timeless-results">
          <div className="results-heading">
            <div><span className="eyebrow">RANKED CANDIDATES</span><h2>{results.length} 個候選結果</h2></div>
            <span>只顯示前 50 筆</span>
          </div>
          {results.length === 0 ? <div className="empty-results">沒有結果；降低最低次數或分數再試一次。</div> : (
            <div className="timeless-result-grid">
              {results.map((result) => {
                const key = favoriteKey(result);
                const isFavorite = favorites.some((entry) => entry.key === key);
                return (
                  <article key={key}>
                    <div className="result-seed">
                      <Sparkles size={18} />
                      <span><small>SEED</small><strong>{result.seed}</strong></span>
                      <b>{result.score.toFixed(1)} 分</b>
                    </div>
                    <p>{result.conqueror} · {result.socketId}</p>
                    <div className="result-stats">
                      {Object.entries(result.stats).filter(([, value]) => value > 0).map(([id, value]) => {
                        const stat = timelessStatOptions.find((option) => option.id === id);
                        return <span key={id}>{stat?.label.zhTW ?? id}<strong>×{value}</strong></span>;
                      })}
                    </div>
                    <div className="result-actions">
                      <button onClick={() => void toggleFavorite(result)} className={isFavorite ? "active" : ""} aria-label="收藏候選"><Heart size={15} fill={isFavorite ? "currentColor" : "none"} /></button>
                      <button onClick={() => { void navigator.clipboard.writeText(result.pobText); setMessage(`Seed ${result.seed} 已複製為 PoB 物品文字。`); }}><Clipboard size={15} /> PoB</button>
                      <a href={result.tradeUrl} target="_blank" rel="noreferrer">市集 <ExternalLink size={14} /></a>
                    </div>
                  </article>
                );
              })}
            </div>
          )}
        </section>
      )}
    </div>
  );
}
